     2	import java.util.List;
     3	import java.util.Map;
     4	
     5	/**
     6	 * What a policy covers: the items the office recorded when it wrote the policy,
     7	 * able to say which of them a reported damage is settled on.
     8	 *
     9	 * Reading a damage report against the covered items is a decision of its own,
    10	 * revised on its own schedule and quite apart from what one damage earns or what
    11	 * the cap allows.
    12	 */
    13	record Coverage(List<InsuredItem> insuredItems) {
    14	
    15	    static Coverage of(List<InsuredItem> insuredItems) {
    16	        return new Coverage(List.copyOf(insuredItems));
    17	    }
    18	
    19	    /**
    20	     * What the office requires of an incident before it settles any of it: the
    21	     * damages reported of a kind can be no more than the items of that kind the
    22	     * policy covers, because each damage reported is a separate damage to a
    23	     * separate covered item. An incident reporting more is no claim the office
    24	     * will settle, and it refuses the claim whole rather than settling the part
    25	     * it does cover.
    26	     */
    27	    void requireIncidentIsCovered(List<Damage> damages) {
    28	        for (Map.Entry<String, Integer> reported : countedByKind(damages).entrySet()) {
    29	            if (reported.getValue() > coveredOfKind(reported.getKey())) {
    30	                throw new RejectedScenario("the policy covers fewer items of type "
    31	                        + reported.getKey() + " than the incident reports damaged");
    32	            }
    33	        }
    34	    }
    35	
    36	    private static Map<String, Integer> countedByKind(List<Damage> damages) {
    37	        Map<String, Integer> counts = new LinkedHashMap<>();
    38	        for (Damage damage : damages) {
    39	            counts.merge(damage.itemType(), 1, Integer::sum);
    40	        }
    41	        return counts;
    42	    }
    43	
    44	    private int coveredOfKind(String damagedItemType) {
    45	        int covered = 0;
    46	        for (InsuredItem insuredItem : insuredItems) {
    47	            if (isOfKind(insuredItem, damagedItemType)) {
    48	                covered++;
    49	            }
    50	        }
    51	        return covered;
    52	    }
    53	
    54	    /**
    55	     * The covered item whose terms a reported damage is settled on: the office
    56	     * looks the reported kind of item up among the items it covers, and the
    57	     * claim rules read the clauses from it. A damage naming a kind of item the
    58	     * coverage does not include is no claim the office will settle.
    59	     *
    60	     * The office matches by the kind of item reported. Several covered items of
    61	     * one kind are alike in everything the claim rules read, so which of them a
    62	     * damage is settled on cannot change what it earns; what matters is that
    63	     * there are enough of them, which
    64	     * {@link #requireIncidentIsCovered} has already established.
    65	     */
    66	    InsuredItem itemDamagedBy(Damage damage) {
    67	        for (InsuredItem insuredItem : insuredItems) {
    68	            if (isOfKind(insuredItem, damage.itemType())) {
    69	                return insuredItem;
    70	            }
    71	        }
    72	        throw new RejectedScenario(
    73	                "the policy does not cover an item of type " + damage.itemType());
    74	    }
    75	
    76	    /**
    77	     * Whether a covered item is of the kind a damage report names, which is all
    78	     * the office asks of a covered item to settle a damage on it. Recognizing a
    79	     * damage by something narrower than the kind reported would be a revision of
    80	     * this one sentence.
    81	     */
    82	    private static boolean isOfKind(InsuredItem insuredItem, String damagedItemType) {
    83	        return insuredItem.type().equals(damagedItemType);
    84	    }
    85	}
