     1	import java.math.BigDecimal;
     2	import java.util.List;
     3	
     4	/**
     5	 * A policy the office has written: the {@link Coverage} it was written over and
     6	 * the {@link PayoutCap} it was written under.
     7	 *
     8	 * Settling an incident against the policy is this policy's decision, not the
     9	 * protocol's, and all it decides is how the three parties to a settlement meet:
    10	 * the coverage says which covered item a reported damage is settled on, the
    11	 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
    12	 * of it is actually paid. So the deductible is borne once per damage reported
    13	 * and the cap is consumed in the order the damages are reported.
    14	 */
    15	public class Policy {
    16	
    17	    private final Coverage coverage;
    18	    private final PayoutCap payoutCap;
    19	
    20	    /**
    21	     * The office writes a policy over the items a customer brings: what it
    22	     * insures them for is the {@link PriceList}'s to state, and the cap that
    23	     * insurance sum earns is the cap's own rule. Premium modifiers are no part
    24	     * of it, which is why the policy is written from the covered items and never
    25	     * from the premium quoted for them.
    26	     */
    27	    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
    28	        return new Policy(Coverage.of(insuredItems),
    29	                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
    30	    }
    31	
    32	    private Policy(Coverage coverage, PayoutCap payoutCap) {
    33	        this.coverage = coverage;
    34	        this.payoutCap = payoutCap;
    35	    }
    36	
    37	    /**
    38	     * What the office pays for one reported incident: the sum of what each
    39	     * damage reported is settled for, settled in the order reported so that the
    40	     * cap is consumed in that order. An incident the coverage refuses is settled
    41	     * not at all, so nothing is paid out of a claim the office rejects.
    42	     */
    43	    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
    44	        coverage.requireIncidentIsCovered(damages);
    45	        BigDecimal paid = BigDecimal.ZERO;
    46	        for (Damage damage : damages) {
    47	            paid = paid.add(settleOne(damage, claimPolicy));
    48	        }
    49	        return paid;
    50	    }
    51	
    52	    /**
    53	     * What one reported damage is actually paid: the coverage says which covered
    54	     * item it is settled on, the claim rules say what that damage earns on that
    55	     * item's terms, and the cap pays what it still allows of it.
    56	     *
    57	     * Every damage reported is settled here on its own, which is why a second
    58	     * damage of a kind already damaged bears the deductible again and draws on
    59	     * the cap the first one has already reduced. Settling an incident as a whole
    60	     * instead — one deductible for the incident, or the incident's total tested
    61	     * against the cap in one go — would be a revision of this one sentence.
    62	     */
    63	    private BigDecimal settleOne(Damage damage, ClaimPolicy claimPolicy) {
    64	        InsuredItem damagedItem = coverage.itemDamagedBy(damage);
    65	        return payoutCap.pay(claimPolicy.reimbursementFor(damage.amount(), damagedItem));
    66	    }
    67	
    68	    public BigDecimal remainingCap() {
    69	        return payoutCap.remaining();
    70	    }
    71	}
