     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The limit on everything a policy will ever pay out, and how much of it is
     5	 * left. The office caps a policy at twice the insurance sum of the items it
     6	 * covers.
     7	 *
     8	 * What the cap is worth and what it has left are one decision revised on its
     9	 * own schedule: a revision to the multiple, or one that let the cap replenish,
    10	 * is this cap's business and touches no claim rule. Premium modifiers are no
    11	 * part of it, which is why a cap is opened from an insurance sum and never from
    12	 * a premium.
    13	 */
    14	class PayoutCap {
    15	
    16	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
    17	
    18	    private BigDecimal remaining;
    19	
    20	    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
    21	        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
    22	    }
    23	
    24	    private PayoutCap(BigDecimal remaining) {
    25	        this.remaining = remaining;
    26	    }
    27	
    28	    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
    29	    BigDecimal pay(BigDecimal desiredPayout) {
    30	        BigDecimal paid = desiredPayout.min(remaining);
    31	        remaining = remaining.subtract(paid);
    32	        return paid;
    33	    }
    34	
    35	    BigDecimal remaining() {
    36	        return remaining;
    37	    }
    38	}
