public class ClaimOfficeCli {

    private static final ObjectMapper JSON = new ObjectMapper();

    private static final int ACCEPTED = 0;
    private static final int REJECTED = 1;

    /**
     * Reports the scenario's results, answering the exit status the office
     * exits with: nothing but the results document on stdout when the office
     * accepts the scenario.
     */
    public int report(InputStream scenario, PrintStream results, PrintStream rejection) {
        try {
            results.print(resultsFor(scenario));
            return ACCEPTED;
        } catch (RejectedScenario refusal) {
            rejection.println(refusal.getMessage());
            return REJECTED;
        }
    }

    private String resultsFor(InputStream scenario) {
        try {
            JsonNode input = JSON.readTree(scenario);
            ClaimOffice office =
                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
            ObjectNode output = JSON.createObjectNode();
            ArrayNode resultsNode = output.putArray("results");
            JsonNode steps = input.get("steps");
            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
                JsonNode step = steps.get(stepIndex);
                if ("claim".equals(step.get("op").asText())) {
                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
                            resultsNode.addObject());
                    continue;
                }
                resultsNode.addObject().put("premium",
                        office.quote(stepIndex, insuredItems(step)));
            }
            return JSON.writeValueAsString(output);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
        result.put("payout", settlement.payout().intValueExact());
        result.put("remainingCap", settlement.remainingCap().intValueExact());
    }

    private static List<Damage> damages(JsonNode claimStep) {
        List<Damage> damages = new ArrayList<>();
        for (JsonNode damage : claimStep.get("incident").get("damages")) {
            damages.add(new Damage(damage.get("itemType").asText(),
                    new BigDecimal(damage.get("amount").asText())));
        }
        return damages;
    }

    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
        List<InsuredItem> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new InsuredItem(item.get("type").asText(),
                    item.path("cursed").asBoolean(false),
                    item.path("enchantment").asInt(0)));
        }
        return items;
    }
}

